#!/usr/bin/env bash
# Build an installable (sideloadable) release APK of the Expo app locally on Windows (Git Bash).
#
# Usage (from anywhere):   bash "mobile/scripts/build-apk.sh" [--clean]
#   --clean   regenerate mobile/android from scratch (expo prebuild --clean)
#
# Toolchain (installed user-locally, no admin):
#   JDK 17 (Eclipse Temurin)   -> $TOOLCHAIN/jdk17
#   Android SDK (cmdline-tools, platform-tools, platforms, build-tools, NDK) -> $TOOLCHAIN/sdk
#
# NOTE: mobile/android is generated by `expo prebuild` (Expo CNG) and is git-ignored.
# NOTE: The Expo prebuild template signs the *release* build with the DEBUG keystore
#       (android/app/debug.keystore). That is fine for sideloading/testing, but NOT for Play Store
#       upload, and an APK signed with a different key cannot update this one in place.
# NOTE: EXPO_PUBLIC_* variables are read from mobile/.env at bundle time (inlined into the JS bundle).
set -euo pipefail

TOOLCHAIN="${TOOLCHAIN:-/c/Users/user/android-toolchain}"
export JAVA_HOME="${JAVA_HOME_OVERRIDE:-$TOOLCHAIN/jdk17}"
export ANDROID_HOME="$TOOLCHAIN/sdk"
export ANDROID_SDK_ROOT="$ANDROID_HOME"
export PATH="$JAVA_HOME/bin:$ANDROID_HOME/platform-tools:$ANDROID_HOME/cmdline-tools/latest/bin:$PATH"
export NODE_ENV=production

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
MOBILE_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
ROOT_DIR="$(cd "$MOBILE_DIR/.." && pwd)"
OUT="$ROOT_DIR/dist/site-materials.apk"

PREBUILD_FLAGS=(--platform android --no-install)
if [[ "${1:-}" == "--clean" || ! -d "$MOBILE_DIR/android" ]]; then
  PREBUILD_FLAGS+=(--clean)
fi

start=$(date +%s)
cd "$MOBILE_DIR"
echo ">> expo prebuild ${PREBUILD_FLAGS[*]}"
# prebuild rewrites package.json "scripts.android" to "expo run:android"; keep package.json untouched.
cp package.json "$SCRIPT_DIR/.package.json.bak"
CI=1 npx expo prebuild "${PREBUILD_FLAGS[@]}"
mv -f "$SCRIPT_DIR/.package.json.bak" package.json

# Build tuning (re-applied every run because prebuild --clean regenerates the file):
#  - more Gradle heap; only build the two real-device ABIs (skip x86/x86_64 emulators) to cut build time.
GP="$MOBILE_DIR/android/gradle.properties"
sed -i -E '/^org\.gradle\.jvmargs=/d; /^reactNativeArchitectures=/d' "$GP"
# the generated file may lack a trailing newline — without this the next line gets glued onto the last property
[[ -n "$(tail -c1 "$GP")" ]] && echo >> "$GP"
{
  echo "org.gradle.jvmargs=-Xmx4g -XX:MaxMetaspaceSize=1g -Dfile.encoding=UTF-8"
  echo "reactNativeArchitectures=arm64-v8a,armeabi-v7a"
} >> "$GP"
printf 'sdk.dir=%s\n' "$(cygpath -m "$ANDROID_HOME")" > "$MOBILE_DIR/android/local.properties"

# Prefer ~/.m2 for react-android + kotlin-compiler-embeddable: on slow links Gradle times out downloading these large files,
# so scripts/fetch-maven.sh pre-downloads it with resume. Scoped so nothing else resolves from ~/.m2.
BG="$MOBILE_DIR/android/build.gradle"
if ! grep -q "mavenLocal" "$BG"; then
  sed -i '/^allprojects {/,/^}/ s/^  repositories {$/  repositories {\n    mavenLocal { content { includeModule("com.facebook.react", "react-android"); includeModule("org.jetbrains.kotlin", "kotlin-compiler-embeddable") } }/' "$BG"
fi

cd "$MOBILE_DIR/android"
echo ">> gradlew assembleRelease"
./gradlew assembleRelease --no-configuration-cache

APK="$MOBILE_DIR/android/app/build/outputs/apk/release/app-release.apk"
mkdir -p "$(dirname "$OUT")"
cp -f "$APK" "$OUT"
echo ">> APK: $OUT ($(du -h "$OUT" | cut -f1)) built in $(( ($(date +%s) - start) / 60 )) min"
